export default async function handler(req,res){res.setHeader('content-type','application/json');res.setHeader('Cache-Control','no-store');if(req.method!=='GET'){res.statusCode=405;res.end(JSON.stringify({error:'Method not allowed'}));return;}const address=new URL(req.url,'https://local.invalid').searchParams.get('address');if(!/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(address||'')){res.statusCode=400;res.end(JSON.stringify({error:'Invalid Solana address'}));return;}try{const r=await fetch('https://api.mainnet-beta.solana.com',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'getBalance',params:[address,{commitment:'confirmed'}]}),signal:AbortSignal.timeout(10000)});const j=await r.json();if(j.error||typeof j.result?.value!=='number')throw Error();res.end(JSON.stringify({address,lamports:j.result.value,slot:j.result.context.slot,asOf:new Date().toISOString()}));}catch{res.statusCode=503;res.end(JSON.stringify({error:'Balance temporarily unavailable'}));}}
